#!/usr/bin/env python3
"""Numerical demonstrations for deterministic wetware dynamics.

The program uses only Python's standard library. It demonstrates:
1. exact configuration-information formulas;
2. eventual periodicity of finite deterministic orbits;
3. the constructive one-step realization of a finite function.
"""

from __future__ import annotations

from dataclasses import dataclass
from math import log2
from typing import Callable, Dict, Hashable, Iterable, List, Mapping, Sequence, Tuple, TypeVar

State = TypeVar("State", bound=Hashable)
X = TypeVar("X", bound=Hashable)
Y = TypeVar("Y", bound=Hashable)


@dataclass(frozen=True)
class EnergyRow:
    """One exact information-cost comparison."""

    neurons: int
    wetware_bits: float
    silicon_bits: float
    ratio: float


def energy_row(n: int) -> EnergyRow:
    """Return n log2(n), n^2, and their ratio for a positive integer n."""
    if n < 1:
        raise ValueError("n must be positive")
    wetware = n * log2(n)
    silicon = float(n * n)
    return EnergyRow(n, wetware, silicon, wetware / silicon)


def energy_profile(sizes: Iterable[int]) -> List[EnergyRow]:
    """Evaluate the exact information formulas at selected sizes."""
    return [energy_row(n) for n in sizes]


def find_periodic_tail(
    step: Mapping[State, State], start: State
) -> Tuple[int, int, List[State]]:
    """Find transient length, period, and visited states before repetition.

    The finite transition table must contain every state reached from start.
    """
    first_seen: Dict[State, int] = {}
    orbit: List[State] = []
    current = start
    while current not in first_seen:
        if current not in step:
            raise KeyError(f"missing transition for state {current!r}")
        first_seen[current] = len(orbit)
        orbit.append(current)
        current = step[current]
    transient = first_seen[current]
    period = len(orbit) - transient
    return transient, period, orbit


def verify_periodic_tail(
    step: Mapping[State, State], start: State, transient: int, period: int,
    checks: int = 100
) -> bool:
    """Numerically check x_(a+k+p) = x_(a+k) for a finite range of k."""
    if transient < 0 or period <= 0 or checks < 0:
        return False
    states: List[State] = [start]
    for _ in range(transient + period + checks):
        states.append(step[states[-1]])
    return all(
        states[transient + k + period] == states[transient + k]
        for k in range(checks + 1)
    )


def build_one_step_realization(
    table: Mapping[X, Y]
) -> Tuple[Dict[Tuple[str, Hashable], Tuple[str, Hashable]],
           Callable[[X], Tuple[str, Hashable]],
           Callable[[Tuple[str, Hashable]], Y]]:
    """Construct tagged states realizing a finite function in one transition."""
    outputs = set(table.values())
    transition: Dict[Tuple[str, Hashable], Tuple[str, Hashable]] = {}
    for x, y in table.items():
        transition[("in", x)] = ("out", y)
    for y in outputs:
        transition[("out", y)] = ("out", y)

    def encode(x: X) -> Tuple[str, Hashable]:
        if x not in table:
            raise KeyError(f"unknown input {x!r}")
        return ("in", x)

    def decode(state: Tuple[str, Hashable]) -> Y:
        tag, value = state
        if tag == "out":
            return value  # type: ignore[return-value]
        if tag == "in":
            return table[value]  # type: ignore[index]
        raise ValueError(f"unknown tag {tag!r}")

    return transition, encode, decode


def demonstrate_energy() -> None:
    """Print benchmark values and the decreasing relative information cost."""
    print("CONFIGURATION INFORMATION")
    print(f"{'n':>8} {'n log2 n':>16} {'n^2':>16} {'ratio':>14}")
    for row in energy_profile([1, 2, 4, 8, 16, 64, 256, 1024, 65536]):
        print(
            f"{row.neurons:8d} {row.wetware_bits:16.3f} "
            f"{row.silicon_bits:16.3f} {row.ratio:14.8f}"
        )
    assert energy_row(2).wetware_bits == 2.0
    assert energy_row(2).silicon_bits == 4.0
    assert energy_row(4).wetware_bits == 8.0
    assert energy_row(4).silicon_bits == 16.0


def demonstrate_periodicity() -> None:
    """Expose a transient stem followed by a 3-cycle."""
    transition = {0: 4, 1: 3, 2: 5, 3: 4, 4: 2, 5: 7, 6: 1, 7: 2}
    transient, period, orbit = find_periodic_tail(transition, 0)
    print("\nFINITE ORBIT")
    print("transition table:", transition)
    print("states before first repetition:", orbit)
    print("transient length:", transient)
    print("period:", period)
    print("cycle:", orbit[transient:])
    assert (transient, period) == (2, 3)
    assert verify_periodic_tail(transition, 0, transient, period)


def demonstrate_realization() -> None:
    """Realize a finite nonlinear lookup function in one transition."""
    target = {x: (x * x + 1) % 7 for x in range(7)}
    transition, encode, decode = build_one_step_realization(target)
    computed = {x: decode(transition[encode(x)]) for x in target}
    print("\nONE-STEP REALIZATION")
    print("target function:", target)
    print("computed outputs:", computed)
    print("tagged state count:", len(target) + len(set(target.values())))
    assert computed == target


def main() -> None:
    demonstrate_energy()
    demonstrate_periodicity()
    demonstrate_realization()


if __name__ == "__main__":
    main()
